          "type": "timeline",
          "intent": "Show the brand's growth and momentum through a chronological story that builds credibility and signals longevity.",
          "eyebrow": "Our Journey",
          "headline": "From First Batch to Beloved Brand",
          "subheadline": null,
          "body": null,
          "items": [
            {
              "title": "2019 \u2014 The First Formula",
              "description": "Lavender Dream Butter is made in a home kitchen and shared with 50 friends. The feedback is unanimous: make more.",
              "metadata": {}
            },
            {
              "title": "2020 \u2014 First 1,000 Customers",
              "description": "Lumi & Bloom launches online with four products and sells out within three weeks of its first campaign.",
              "metadata": {}
            },
            {
              "title": "2021 \u2014 Clean Beauty Certified",
              "description": "We receive third-party clean beauty certification and introduce our first refillable packaging option.",
              "metadata": {}
            },
            {
              "title": "2022 \u2014 Community Co-Creation",
              "description": "The Citrus Burst Sugar Scrub is developed entirely based on community votes and ingredient suggestions.",
              "metadata": {}
            },
            {
              "title": "2023 \u2014 50,000 Customers & Counting",
              "description": "We cross 50,000 happy customers and launch our sustainability pledge: plastic-free packaging by 2026.",
              "metadata": {}
            }
          ],
          "ctas": [],
          "asset_ideas": [
            {
              "id": "brand-section-4-asset-1",
              "kind": "icon",
              "subject": "A set of five simple milestone icons: a jar, a star, a leaf, a group of people, and a globe \u2014 one for each timeline step.",
              "purpose": "Visual markers for each timeline entry that make the brand journey scannable and emotionally engaging.",
              "quantity": 1,
              "used_by": [
                "brand-section-4"
