  left: 50%;
  width: 2px;
  background: var(--aqua-bloom);
  transform: translateX(-50%);
}

.sus-tl-item {
  position: relative;
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  margin-bottom: 48px;
  gap: 0;
}

.sus-tl-item:last-child {
  margin-bottom: 0;
}

.sus-tl-item__dot {
  position: absolute;
  left: 50%;
  top: 60px;
  transform: translate(-50%, -50%);
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--aqua-bloom);
  z-index: 2;
}

.sus-tl-item__content {
  padding: 0 40px;
}

.sus-tl-item--right .sus-tl-item__content {
  grid-column: 2 / 3;
  text-align: left;
}

.sus-tl-item--left .sus-tl-item__content {
  grid-column: 1 / 2;
  text-align: right;
}

.sus-tl-item__year {
  font-family: var(--font-accent);
  font-size: clamp(40px, 6vw, 72px);
  color: var(--sunshine-butter);
  line-height: 1;
}

.sus-tl-item__title {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 20px;
  color: var(--bloom-milk);
  margin-top: 8px;
}

.sus-tl-item__desc {
  margin-top: 8px;
  font-size: 15px;
  color: rgba(255, 248, 244, 0.75);
  line-height: 1.65;
  max-width: 340px;
}

.sus-tl-item--right .sus-tl-item__desc {
  margin-left: 0;
  margin-right: auto;
}

.sus-tl-item--left .sus-tl-item__desc {
  margin-left: auto;
  margin-right: 0;
}

.status-badge {
  display: inline-block;
  margin-top: 12px;
  padding: 8px 16px;
  border-radius: var(--radius-pill);
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--deep-petal);
}

.status-badge--complete { background: var(--petal-mint); }
.status-badge--in-progress { background: var(--aqua-bloom); }
.status-badge--planned { background: var(--glow-peach); }

/* Sustainability CTA */
.sus-cta {
  background: var(--lumi-coral);
  padding: 88px 0;
  text-align: center;
  color: #fff;
}

.sus-cta__inner {
  max-width: 640px;
  margin-inline: auto;
}

.sus-cta h2 {
  font-size: clamp(32px, 4.5vw, 52px);
  font-weight: 800;
  color: var(--bloom-milk);
  margin-top: 12px;
  line-height: 1.15;
}

.sus-cta h2 .accent-butter {
  color: var(--sunshine-butter);
}

.sus-cta p {
  margin-top: 16px;
  font-size: 17px;
  color: rgba(255, 248, 244, 0.85);
  max-width: 520px;
  margin-inline: auto;
  line-height: 1.65;
}

/* ============================================
   CONTACT PAGE
   ============================================ */

.contact-header {
  background: var(--bloom-milk);
  padding: 96px 0 80px;
  position: relative;
  overflow: hidden;
}

.contact-header::before {
  content: "";
  position: absolute;
  top: -100px;
  right: -100px;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, var(--glow-peach) 0%, transparent 70%);
  opacity: 0.7;
  pointer-events: none;
}

.contact-header__inner {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: 7fr 5fr;
  align-items: center;
  gap: 32px;
}

.contact-header h1 {
  font-size: clamp(40px, 6vw, 68px);
  margin-top: 20px;
  font-weight: 800;
  letter-spacing: -0.02em;
}

.contact-header p {
  margin-top: 24px;
  font-size: 18px;
  color: rgba(45, 58, 53, 0.7);
  max-width: 520px;
  line-height: 1.65;
}

.contact-header__illo {
  width: 100%;
  max-width: 360px;
  margin-left: auto;
}

.contact-header__rule {
  height: 2px;
  background: var(--glow-peach);
  margin-top: 48px;
}

/* Contact block */
.contact-block {
  background: var(--soft-cloud);
  padding: 80px 0;
}

.contact-block__inner {
  display: grid;
  grid-template-columns: 7fr 5fr;
  gap: 40px;
  align-items: start;
}

.contact-block__head {
  margin-bottom: 24px;
}

.contact-block__head h2 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: clamp(26px, 4vw, 38px);
  color: var(--deep-petal);
  margin-top: 8px;
}

.contact-block__head p {
  margin-top: 12px;
  font-size: 16px;
  color: rgba(45, 58, 53, 0.65);
  max-width: 420px;
}

.contact-form {
  background: var(--bloom-milk);
  border-radius: var(--radius-lg);
  padding: 32px;
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.contact-form__field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.contact-form__field label {
  font-family: var(--font-body);
  font-weight: 600;
  font-size: 14px;
  color: var(--deep-petal);
}

.contact-form__field input,
.contact-form__field select,
.contact-form__field textarea {
  font-family: var(--font-body);
  font-size: 16px;
  color: var(--deep-petal);
  background: var(--bloom-milk);
  border: 2px solid var(--petal-mint);
  border-radius: var(--radius-sm);
  padding: 12px 14px;
  outline: none;
  transition: border-color 0.18s ease;
}

.contact-form__field textarea {
  resize: vertical;
  min-height: 140px;
  font-family: var(--font-body);
}

.contact-form__field input:focus,
.contact-form__field select:focus,
.contact-form__field textarea:focus {
  border-color: var(--aqua-bloom);
}

.contact-form button[type="submit"] {
  margin-top: 6px;
  width: 100%;
  background: var(--lumi-coral);
  color: var(--bloom-milk);
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 17px;
  padding: 16px;
  border-radius: 14px;
  border: none;
  cursor: pointer;
  transition: background 0.18s ease, transform 0.18s ease;
}

.contact-form button[type="submit"]:hover {
  background: var(--lumi-coral-deep);
  transform: scale(1.02);
}

.contact-cards {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.contact-card {
  background: var(--bloom-milk);
  border-radius: 16px;
  border-left: 4px solid var(--petal-mint);
  padding: 20px;
}

.contact-card__title {
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 18px;
  color: var(--deep-petal);
}

.contact-card__desc {
  margin-top: 6px;
  font-size: 15px;
  color: rgba(45, 58, 53, 0.75);
  line-height: 1.55;
}

.contact-card__email {
  display: inline-block;
  margin-top: 10px;
  color: var(--aqua-bloom);
  font-weight: 500;
  font-size: 15px;
  border-bottom: 1px solid currentColor;
}

/* FAQ */
.contact-faq {
  background: var(--petal-mint);
  padding: 72px 0;
}

.contact-faq__inner {
  display: grid;
  grid-template-columns: 22% 1fr;
  gap: 32px;
}

.contact-faq__side {
  position: relative;
}

.contact-faq__watermark {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: 80px;
  color: var(--deep-petal);
  opacity: 0.15;
  transform: rotate(-90deg);
  transform-origin: left top;
  position: absolute;
  top: 240px;
  left: 32px;
  letter-spacing: -0.02em;
  line-height: 1;
  white-space: nowrap;
}

.contact-faq__main h2 {
  font-size: clamp(26px, 4vw, 36px);
  margin-bottom: 32px;
}

.faq-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.faq-item {
  background: var(--bloom-milk);
  border-radius: 16px;
  overflow: hidden;
}

.faq-item__head {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 20px 24px;
  background: transparent;
  border: none;
  cursor: pointer;
  text-align: left;
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 19px;
  color: var(--deep-petal);
}

.faq-item__icon {
  width: 28px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-accent);
  font-size: 22px;
  color: var(--lumi-coral);
  transition: transform 0.2s ease, color 0.2s ease;
  flex-shrink: 0;
  margin-left: 16px;
}

.faq-item.is-open .faq-item__icon {
  transform: rotate(45deg);
  color: var(--aqua-bloom);
}

.faq-item__body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
  border-top: 0 solid var(--petal-mint);
  padding: 0 24px;
}

.faq-item.is-open .faq-item__body {
  max-height: 320px;
  padding: 16px 24px 22px;
  border-top-width: 2px;
}

.faq-item__body p {
  margin: 0;
  font-size: 16px;
  color: rgba(45, 58, 53, 0.75);
  line-height: 1.65;
}

/* Contact feature grid (Stay Connected) */
.contact-connect {
  background: var(--bloom-milk);
  padding: 80px 0;
}

.contact-connect__head {
  text-align: center;
  max-width: 700px;
  margin: 0 auto 48px;
}

.contact-connect__eyebrow-badge {
  display: inline-block;
  background: var(--deep-petal);
  color: var(--sunshine-butter);
  font-family: var(--font-accent);
  font-size: 12px;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  padding: 6px 14px;
  border-radius: 8px;
}

.contact-connect__head h2 {
  font-size: clamp(26px, 4vw, 38px);
  margin-top: 16px;
}

.contact-connect__head p {
  margin-top: 12px;
  font-size: 17px;
  color: rgba(45, 58, 53, 0.65);
  max-width: 560px;
  margin-inline: auto;
}

.connect-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
  max-width: 1100px;
  margin-inline: auto;
}

.connect-card {
  background: var(--soft-cloud);
  border-radius: var(--radius-lg);
  padding: 32px;
  position: relative;
  border-bottom: 3px solid transparent;
  transition: border-color 0.18s ease, box-shadow 0.18s ease, transform 0.18s ease;
}

.connect-card:hover {
  border-bottom-color: var(--lumi-coral);
  box-shadow: 0 4px 16px rgba(45, 58, 53, 0.08);
  transform: translateY(-2px);
}

.connect-card__icon-wrap {
  width: 72px;
  height: 72px;
  border-radius: 50%;
  background: var(--bloom-milk);
  border: 2px solid var(--petal-mint);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 16px;
}

.connect-card__icon-wrap svg {
  width: 32px;
  height: 32px;
}

.connect-card h3 {
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 22px;
  color: var(--deep-petal);
  margin-bottom: 10px;
}

.connect-card p {
  font-size: 15px;
  color: rgba(45, 58, 53, 0.7);
  line-height: 1.55;
}

.connect-card__tag {
  display: inline-block;
  margin-top: 14px;
  font-family: var(--font-accent);
  font-size: 12px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 6px 12px;
  border-radius: var(--radius-pill);
}

.connect-card__tag--aqua { background: var(--aqua-bloom); color: #fff; }
.connect-card__tag--butter { background: var(--sunshine-butter); color: var(--deep-petal); }
.connect-card__tag--mint { background: var(--petal-mint); color: var(--deep-petal); }

/* Contact CTA */
.contact-cta {
  background: var(--lumi-coral);
  padding: 88px 0;
  text-align: center;
  color: #fff;
  position: relative;
}

.contact-cta__inner {
  position: relative;
  max-width: 720px;
  margin-inline: auto;
}

.contact-cta__sticker {
  position: absolute;
  top: -40px;
  right: 8%;
  width: 96px;
  height: 96px;
  background: var(--sunshine-butter);
  border-radius: 48% 52% 50% 50% / 50% 48% 52% 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--deep-petal);
  transform: rotate(-12deg);
  box-shadow: 0 6px 18px rgba(45, 58, 53, 0.18);
  z-index: 2;
  line-height: 1.1;
  padding: 8px;
}

.contact-cta h2 {
  font-size: clamp(32px, 5vw, 56px);
  font-weight: 800;
  color: var(--bloom-milk);
  margin-top: 16px;
  line-height: 1.1;
}

.contact-cta p {
  margin-top: 14px;
  font-size: 18px;
  color: rgba(255, 248, 244, 0.85);
  max-width: 480px;
  margin-inline: auto;
  line-height: 1.6;
}

.contact-cta .btn--primary {
  background: var(--bloom-milk);
  color: var(--lumi-coral);
}

.contact-cta .btn--primary:hover {
  background: #fff;
}

/* ============================================
   RESPONSIVE
   ============================================ */
@media (max-width: 1024px) {
  .home-hero__inner { grid-template-columns: 1fr; text-align: center; }
  .home-hero__text { margin-inline: auto; }
  .home-hero__bloom { position: static; transform: none; width: 280px; height: 280px; margin: 32px auto 0; }
  .home-gallery { padding-top: 80px; }

  .home-gallery__grid { grid-template-columns: repeat(2, 1fr); }
  .stats-row { grid-template-columns: repeat(2, 1fr); row-gap: 32px; }
  .stats-row__cell + .stats-row__cell::before { display: none; }
  .home-testimonials__cards { grid-template-columns: 1fr; }

  .brand-story__inner { grid-template-columns: 1fr; gap: 32px; }
  .brand-story__quote { margin-left: 0; }

  .products-gallery__grid { grid-template-columns: repeat(2, 1fr); }
  .compare-grid { grid-template-columns: repeat(2, 1fr); }
  .std-grid { grid-template-columns: repeat(2, 1fr); }

  .sus-stats__inner { grid-template-columns: 1fr; }
  .pillar-grid { grid-template-columns: repeat(2, 1fr); }
  .sus-tl-item { grid-template-columns: 1fr; }
  .sus-timeline__list::before { left: 20px; }
  .sus-tl-item__dot { left: 20px; }
  .sus-tl-item__content { padding-left: 56px !important; padding-right: 0 !important; text-align: left !important; grid-column: 1 / 2 !important; }
  .sus-tl-item__desc { margin-left: 0 !important; margin-right: auto !important; }

  .contact-header__inner { grid-template-columns: 1fr; text-align: left; }
  .contact-header__illo { max-width: 240px; margin: 24px auto 0; }
  .contact-block__inner { grid-template-columns: 1fr; }
  .contact-faq__inner { grid-template-columns: 1fr; }
  .contact-faq__watermark { display: none; }
  .connect-grid { grid-template-columns: 1fr; }

  .site-footer__grid { grid-template-columns: 1fr 1fr; }
  .products-header__inner { max-width: 100%; }
}

@media (max-width: 720px) {
  body { font-size: 16px; }
  .container { width: min(100% - 32px, var(--container)); }
  .container-narrow { width: min(100% - 32px, var(--container-narrow)); }

  .home-hero { padding: 64px 0 32px; }
  .home-hero__bloom { width: 240px; height: 240px; }
  .home-gallery { padding: 64px 0 48px; }
  .home-gallery__grid { grid-template-columns: 1fr; }
  .home-testimonials { padding: 56px 0; }
  .home-testimonials__big-quote { font-size: 80px; top: -10px; }

  .site-nav { gap: 12px; }
  .site-nav a { font-size: 13px; }
  .site-nav__cta { display: none !important; }

  .stats-row__num { font-size: 44px; }
  .home-cta { padding: 72px 0; }

  .brand-story { padding: 56px 0; }
  .brand-values { padding: 56px 0; }
  .brand-timeline { padding: 56px 0; }
  .brand-cta { padding: 64px 0; }
  .value-grid { grid-template-columns: 1fr; }

  .products-gallery__floating { font-size: 48px; left: 12px; top: 24px; }
  .products-gallery__eyebrow { margin-bottom: 64px; }
  .products-gallery__grid { grid-template-columns: 1fr; }
  .compare-grid { grid-template-columns: 1fr; }
  .std-grid { grid-template-columns: repeat(2, 1fr); gap: 24px; }
  .products-features__cta { flex-direction: column; align-items: flex-start; }
  .products-cta { padding: 72px 0; }

  .pillar-grid { grid-template-columns: 1fr; }
  .sus-stats__cards { grid-template-columns: 1fr; }
  .sus-timeline { padding: 56px 0; }
  .sus-tl-item__content { padding-left: 44px !important; }
  .sus-cta { padding: 64px 0; }

  .contact-header { padding: 64px 0 48px; }
  .contact-block { padding: 56px 0; }
  .contact-form { padding: 24px; }
  .contact-faq { padding: 56px 0; }
  .contact-connect { padding: 56px 0; }
  .contact-cta { padding: 64px 0; }
  .contact-cta__sticker { right: 16px; width: 80px; height: 80px; }

  .site-footer__grid { grid-template-columns: 1fr; gap: 32px; }
  .site-footer__bottom { flex-direction: column; gap: 8px; }
}

