  text-align: center;
  color: #fff;
  position: relative;
}

.contact-cta__inner {
  position: relative;
  max-width: 720px;
  margin-inline: auto;
}

.contact-cta__sticker {
  position: absolute;
  top: -40px;
  right: 8%;
  width: 96px;
  height: 96px;
  background: var(--sunshine-butter);
  border-radius: 48% 52% 50% 50% / 50% 48% 52% 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--deep-petal);
  transform: rotate(-12deg);
  box-shadow: 0 6px 18px rgba(45, 58, 53, 0.18);
  z-index: 2;
  line-height: 1.1;
  padding: 8px;
}

.contact-cta h2 {
  font-size: clamp(32px, 5vw, 56px);
  font-weight: 800;
  color: var(--bloom-milk);
  margin-top: 16px;
  line-height: 1.1;
}

.contact-cta p {
  margin-top: 14px;
  font-size: 18px;
  color: rgba(255, 248, 244, 0.85);
  max-width: 480px;
  margin-inline: auto;
  line-height: 1.6;
}

.contact-cta .btn--primary {
  background: var(--bloom-milk);
  color: var(--lumi-coral);
}

.contact-cta .btn--primary:hover {
  background: #fff;
}

/* ============================================
   RESPONSIVE
   ============================================ */
@media (max-width: 1024px) {
  .home-hero__inner { grid-template-columns: 1fr; text-align: center; }
  .home-hero__text { margin-inline: auto; }
  .home-hero__bloom { position: static; transform: none; width: 280px; height: 280px; margin: 32px auto 0; }
  .home-gallery { padding-top: 80px; }

  .home-gallery__grid { grid-template-columns: repeat(2, 1fr); }
  .stats-row { grid-template-columns: repeat(2, 1fr); row-gap: 32px; }
  .stats-row__cell + .stats-row__cell::before { display: none; }
  .home-testimonials__cards { grid-template-columns: 1fr; }

  .brand-story__inner { grid-template-columns: 1fr; gap: 32px; }
  .brand-story__quote { margin-left: 0; }

  .products-gallery__grid { grid-template-columns: repeat(2, 1fr); }
  .compare-grid { grid-template-columns: repeat(2, 1fr); }
  .std-grid { grid-template-columns: repeat(2, 1fr); }

  .sus-stats__inner { grid-template-columns: 1fr; }
  .pillar-grid { grid-template-columns: repeat(2, 1fr); }
  .sus-tl-item { grid-template-columns: 1fr; }
  .sus-timeline__list::before { left: 20px; }
  .sus-tl-item__dot { left: 20px; }
  .sus-tl-item__content { padding-left: 56px !important; padding-right: 0 !important; text-align: left !important; grid-column: 1 / 2 !important; }
  .sus-tl-item__desc { margin-left: 0 !important; margin-right: auto !important; }

  .contact-header__inner { grid-template-columns: 1fr; text-align: left; }
  .contact-header__illo { max-width: 240px; margin: 24px auto 0; }
  .contact-block__inner { grid-template-columns: 1fr; }
  .contact-faq__inner { grid-template-columns: 1fr; }
  .contact-faq__watermark { display: none; }
  .connect-grid { grid-template-columns: 1fr; }

  .site-footer__grid { grid-template-columns: 1fr 1fr; }
  .products-header__inner { max-width: 100%; }
}

@media (max-width: 720px) {
  body { font-size: 16px; }
  .container { width: min(100% - 32px, var(--container)); }
  .container-narrow { width: min(100% - 32px, var(--container-narrow)); }

  .home-hero { padding: 64px 0 32px; }
  .home-hero__bloom { width: 240px; height: 240px; }
  .home-gallery { padding: 64px 0 48px; }
  .home-gallery__grid { grid-template-columns: 1fr; }
  .home-testimonials { padding: 56px 0; }
  .home-testimonials__big-quote { font-size: 80px; top: -10px; }

  .site-nav { gap: 12px; }
  .site-nav a { font-size: 13px; }
  .site-nav__cta { display: none !important; }

  .stats-row__num { font-size: 44px; }
  .home-cta { padding: 72px 0; }

  .brand-story { padding: 56px 0; }
  .brand-values { padding: 56px 0; }
  .brand-timeline { padding: 56px 0; }
  .brand-cta { padding: 64px 0; }
  .value-grid { grid-template-columns: 1fr; }

  .products-gallery__floating { font-size: 48px; left: 12px; top: 24px; }
  .products-gallery__eyebrow { margin-bottom: 64px; }
  .products-gallery__grid { grid-template-columns: 1fr; }
  .compare-grid { grid-template-columns: 1fr; }
  .std-grid { grid-template-columns: repeat(2, 1fr); gap: 24px; }
  .products-features__cta { flex-direction: column; align-items: flex-start; }
  .products-cta { padding: 72px 0; }

  .pillar-grid { grid-template-columns: 1fr; }
  .sus-stats__cards { grid-template-columns: 1fr; }
  .sus-timeline { padding: 56px 0; }
  .sus-tl-item__content { padding-left: 44px !important; }
  .sus-cta { padding: 64px 0; }

  .contact-header { padding: 64px 0 48px; }
  .contact-block { padding: 56px 0; }
  .contact-form { padding: 24px; }
  .contact-faq { padding: 56px 0; }
  .contact-connect { padding: 56px 0; }
  .contact-cta { padding: 64px 0; }
  .contact-cta__sticker { right: 16px; width: 80px; height: 80px; }

  .site-footer__grid { grid-template-columns: 1fr; gap: 32px; }
  .site-footer__bottom { flex-direction: column; gap: 8px; }
}

input.content:
// Lumi & Bloom — visual interactions only

(function () {
  'use strict';

  // FAQ accordion
  const faqItems = document.querySelectorAll('.faq-item');
  faqItems.forEach((item) => {
    const head = item.querySelector('.faq-item__head');
    if (!head) return;
    head.addEventListener('click', () => {
      const isOpen = item.classList.contains('is-open');
      faqItems.forEach((other) => {
        other.classList.remove('is-open');
        const btn = other.querySelector('.faq-item__head');
        if (btn) btn.setAttribute('aria-expanded', 'false');
      });
      if (!isOpen) {
        item.classList.add('is-open');
        head.setAttribute('aria-expanded', 'true');
      }
    });
  });

  // Contact form — visual-only feedback
  const form = document.querySelector('.contact-form');
  if (form) {
    form.addEventListener('submit', (e) => {
      e.preventDefault();
      const btn = form.querySelector('button[type="submit"]');
      if (!btn) return;
      const original = btn.textContent;
      btn.textContent = 'Message Sent ✓';
      btn.style.background = '#5BC8D0';
      setTimeout(() => {
        btn.textContent = original;
        btn.style.background = '';
        form.reset();
      }, 2200);
    });
  }

  // Catalog "Add to Ritual" — visual-only feedback
  document.querySelectorAll('.catalog-card__btn').forEach((btn) => {
    btn.addEventListener('click', () => {
      const original = btn.textContent;
      btn.textContent = 'Added ✓';
      btn.style.background = '#2D3A35';
      setTimeout(() => {
        btn.textContent = original;
        btn.style.background = '';
      }, 1400);
    });
  });
})();

